    21→function assert(cond, msg) { if (!cond) throw new Error(msg ?? 'Assertion failed'); }
    22→function eq(a, b) { if (a !== b) throw new Error(`Expected ${JSON.stringify(b)}, got ${JSON.stringify(a)}`); }
