    26→const PORT_COMPAT = {
    27→  component: ['component', 'any'],
    28→  data:      ['data', 'any'],
    29→  logic:     ['logic', 'any'],
    30→  event:     ['event', 'any'],
    31→  any:       ['component', 'data', 'logic', 'event', 'any'],
    32→};
    33→
    34→function isCompatible(outType, inType) {
    35→  return (PORT_COMPAT[outType] ?? []).includes(inType);
    36→}
