    40→// 1. 포트 호환성
    41→test('component → component 연결 가능', () => assert(isCompatible('component', 'component')));
    42→test('data → data 연결 가능', () => assert(isCompatible('data', 'data')));
    43→test('logic → logic 연결 가능', () => assert(isCompatible('logic', 'logic')));
    44→test('event → event 연결 가능', () => assert(isCompatible('event', 'event')));
    45→test('any → 모든 타입 가능', () => {
    46→  for (const t of ['component','data','logic','event','any']) {
