    50→test('component → data 연결 불가', () => assert(!isCompatible('component', 'data')));
    51→test('data → logic 연결 불가', () => assert(!isCompatible('data', 'logic')));
    52→test('logic → component 연결 불가', () => assert(!isCompatible('logic', 'component')));
    53→test('data → any 연결 가능', () => assert(isCompatible('data', 'any')));
    54→test('logic → any 연결 가능', () => assert(isCompatible('logic', 'any')));
