    56→// 2. 베지어 곡선 생성
    57→function bez(x1,y1,x2,y2) {
    58→  const dx = Math.abs(x2-x1)*0.6+40;
    59→  return `M ${x1} ${y1} C ${x1+dx} ${y1}, ${x2-dx} ${y2}, ${x2} ${y2}`;
    60→}
