    78→// 3. 그래프 직렬화 로직
    79→
    80→class GraphModel {
    81→  constructor() {
    82→    this.nodes = new Map();
    83→    this.wires = new Map();
    84→    this.nodeCtr = 1;
    85→    this.wireCtr = 1;
    86→  }
    87→
    88→  addNode(def, x=100, y=100) {
    89→    const id = `n${this.nodeCtr++}`;
    90→    this.nodes.set(id, { id, ...def, x, y });
    91→    return id;
    92→  }
    93→
    94→  removeNode(id) {
    95→    for (const [wid, w] of this.wires) {
    96→      if (w.fn===id || w.tn===id) this.wires.delete(wid);
    97→    }
    98→    this.nodes.delete(id);
    99→  }
   100→
   101→  addWire(fn, fp, tn, tp, pt) {
   102→    // 중복 방지
   103→    for (const w of this.wires.values()) {
   104→      if (w.fn===fn && w.fp===fp && w.tn===tn && w.tp===tp) return null;
   105→    }
   106→    const id = `w${this.wireCtr++}`;
   107→    this.wires.set(id, { id, fn, fp, tn, tp, pt });
   108→    return id;
   109→  }
   110→
   111→  toJSON() {
   112→    const nodes = {};
   113→    for (const [id, n] of this.nodes) nodes[id] = { ...n };
   114→    const edges = [...this.wires.values()].map(w=>({...w}));
   115→    return { id:'test-graph', nodes, edges };
   116→  }
   117→
   118→  fromJSON(json) {
   119→    this.nodes.clear(); this.wires.clear();
   120→    for (const [id, nd] of Object.entries(json.nodes??{})) this.nodes.set(id, nd);
   121→    for (const e of json.edges??[]) this.wires.set(e.id, e);
   122→  }
   123→}
