   205→// 4. 로컬 컴파일러 로직
   206→
   207→function localCompile(graph) {
   208→  const nodes = Object.values(graph.nodes ?? {});
   209→  const comps = nodes.filter(n => n.type === 'component');
   210→  const states = nodes.filter(n => n.type === 'data' && n.subtype === 'state');
   211→  const lines = ['component MyApp {'];
   212→  if (states.length) {
   213→    lines.push('  state {');
   214→    for (const s of states) lines.push(`    ${s.props?.name??'val'}: ${s.props?.initial??'0'}`);
   215→    lines.push('  }');
   216→  }
   217→  if (comps.length) {
   218→    lines.push('  markup {');
   219→    for (const c of comps) {
   220→      const p = Object.entries(c.props??{}).map(([k,v])=>`${k}: "${v}"`).join(', ');
   221→      lines.push(`    ${c.subtype}(${p})`);
   222→    }
   223→    lines.push('  }');
   224→  }
   225→  lines.push('}');
   226→  return lines.join('\n');
   227→}
