   310→// 6. 뷰포트 계산
   311→
   312→function fitViewCalc(nodes, canvasW, canvasH) {
   313→  if (!nodes.length) return { x:0, y:0, scale:1 };
   314→  const nw = 190, nh = 120;
   315→  let minX=Infinity, minY=Infinity, maxX=-Infinity, maxY=-Infinity;
   316→  for (const n of nodes) {
   317→    minX=Math.min(minX,n.x); minY=Math.min(minY,n.y);
   318→    maxX=Math.max(maxX,n.x+nw); maxY=Math.max(maxY,n.y+nh);
   319→  }
   320→  const pw=canvasW-60, ph=canvasH-200;
   321→  const scale = Math.max(0.2,Math.min(1.5,Math.min(pw/(maxX-minX||1),ph/(maxY-minY||1))));
   322→  const x = (canvasW-(maxX-minX)*scale)/2 - minX*scale;
   323→  const y = (ph-(maxY-minY)*scale)/2 - minY*scale + 20;
   324→  return { x, y, scale };
   325→}
   326→
   327→test('fitView: 단일 노드', () => {
   328→  const r = fitViewCalc([{x:0,y:0}], 800, 600);
   329→  assert(r.scale > 0, '스케일 양수');
   330→  assert(r.scale <= 1.5, '최대 스케일 이하');
   331→});
   332→
   333→test('fitView: 스케일 범위 유지', () => {
   334→  const r1 = fitViewCalc([{x:0,y:0},{x:5000,y:5000}], 800, 600);
   335→  assert(r1.scale >= 0.2, '최소 스케일');
   336→  const r2 = fitViewCalc([{x:0,y:0},{x:10,y:10}], 800, 600);
   337→  assert(r2.scale <= 1.5, '최대 스케일');
   338→});
   339→
   340→test('fitView: 빈 노드 목록', () => {
   341→  const r = fitViewCalc([], 800, 600);
   342→  eq(r.scale, 1); eq(r.x, 0); eq(r.y, 0);
   343→});
