    97→
    98→// ─── 의도 파서 ────────────────────────────────────────────────────
    99→
   100→class IntentParser {
   101→  parse(text) {
   102→    const t = text.toLowerCase().trim();
   103→
   104→    // 1) 직접 패턴
   105→    for (const [pattern, intent] of PATTERNS) {
   106→      if (pattern.test(t)) return { ...intent, raw: text };
   107→    }
   108→
   109→    // 2) 키워드 추출로 복합 의도
   110→    const keywords = this._extractKeywords(t);
   111→    return this._buildFromKeywords(keywords, text);
   112→  }
   113→
   114→  _extractKeywords(t) {
   115→    const kw = { components: [], data: [], logic: [], style: 'column', title: null };
   116→
   117→    // 제목
   118→    const titleMatch = t.match(/["']([^"']+)["']/) || t.match(/제목[은이]?\s*(.+?)(?:\s+|$)/);
   119→    if (titleMatch) kw.title = titleMatch[1];
   120→
   121→    // 컴포넌트
   122→    if (/(버튼|button|클릭|submit|제출|확인|취소|저장|삭제|추가)/.test(t)) kw.components.push('button');
   123→    if (/(텍스트|text|제목|title|label|표시|출력)/.test(t)) kw.components.push('text');
   124→    if (/(입력|input|필드|field|이메일|email|비밀번호|password|이름|name|검색|search)/.test(t)) kw.components.push('input');
   125→    if (/(카드|card)/.test(t)) kw.components.push('card');
   126→    if (/(리스트|list|목록|항목)/.test(t)) kw.components.push('list');
   127→
   128→    // 데이터
   129→    if (/(상태|state|카운트|count)/.test(t)) kw.data.push('state');
   130→    if (/(배열|array|list|목록|아이템)/.test(t)) kw.data.push('array');
   131→
   132→    // 로직
   133→    if (/(핸들러|클릭|이벤트|handler|event|onClick)/.test(t)) kw.logic.push('handler');
   134→    if (/(조건|if|else|분기)/.test(t)) kw.logic.push('condition');
   135→
   136→    // 레이아웃
   137→    if (/(가로|row|수평|horizontal)/.test(t)) kw.style = 'row';
   138→
   139→    return kw;
   140→  }
   141→
   142→  _buildFromKeywords(kw, raw) {
   143→    // 컴포넌트가 없으면 일반 텍스트로
   144→    if (kw.components.length === 0 && kw.data.length === 0) {
   145→      return { type: 'generic', label: raw, raw };
   146→    }
   147→    return { type: 'custom', keywords: kw, raw };
   148→  }
   149→}
   150→
   151→// 고정 패턴
   152→const PATTERNS = [
   153→  [/로그인|login|sign.?in/, { type: 'login' }],
   154→  [/회원가입|register|sign.?up/, { type: 'register' }],
   155→  [/카운터|counter|숫자\s*세기/, { type: 'counter' }],
   156→  [/검색|search/, { type: 'search' }],
   157→  [/(할일|todo|task)\s*(리스트|list|목록)?/, { type: 'todo' }],
   158→  [/(프로필|profile)\s*(카드|card)?/, { type: 'profile-card' }],
   159→  [/(댓글|comment)\s*(폼|form)?/, { type: 'comment-form' }],
   160→  [/(결제|payment|checkout)\s*(폼|form)?/, { type: 'checkout' }],
   161→  [/(설정|setting|config)\s*(폼|form|페이지)?/, { type: 'settings' }],
   162→  [/(대시보드|dashboard)/, { type: 'dashboard' }],
   163→  [/(모달|modal|팝업|popup)/, { type: 'modal' }],
   164→  [/네비게이션|navbar|nav\s*bar/, { type: 'navbar' }],
   165→  [/버튼/, { type: 'single-button' }],
   166→  [/카드/, { type: 'single-card' }],
   167→  [/(입력|input)\s*(폼|form)/, { type: 'input-form' }],
   168→];
   169→
   170→// ─── 템플릿 엔진 ──────────────────────────────────────────────────
   171→
   172→class TemplateEngine {
   173→  generate(intent) {
   174→    const gen = TEMPLATES[intent.type];
   175→    if (gen) return gen(intent);
   176→
   177→    // 커스텀 키워드 기반
   178→    if (intent.type === 'custom') return this._generateCustom(intent);
   179→
   180→    // 폴백: 단순 텍스트 + 버튼
   181→    return this._generateFallback(intent.raw);
   182→  }
   183→
   184→  _generateCustom(intent) {
   185→    const { keywords } = intent;
   186→    const nodes = [], edges = [];
   187→    let hasContainer = keywords.components.length > 1;
   188→    let container = null;
   189→
   190→    if (hasContainer) {
   191→      container = NODE.container(keywords.style);
   192→      nodes.push(container);
   193→    }
   194→
   195→    // 데이터 먼저
   196→    let stateNode = null;
   197→    if (keywords.data.includes('state')) {
   198→      stateNode = NODE.state('value', '0');
   199→      nodes.push(stateNode);
   200→    }
   201→
   202→    let arrayNode = null;
   203→    if (keywords.data.includes('array')) {
   204→      arrayNode = NODE.array('["항목1","항목2","항목3"]');
   205→      nodes.push(arrayNode);
   206→    }
   207→
   208→    // 컴포넌트
   209→    for (const c of keywords.components) {
   210→      let n;
   211→      if (c === 'button') {
   212→        n = NODE.button('확인');
   213→        nodes.push(n);
   214→        // 핸들러 연결
   215→        if (keywords.logic.includes('handler')) {
   216→          const h = NODE.handler('handleClick');
   217→          nodes.push(h);
   218→          edges.push({ fn: h.id, fp: 0, tn: n.id, tp: 1 });
   219→        }
   220→      } else if (c === 'text') {
   221→        n = NODE.text(keywords.title ?? '텍스트', 'p');
   222→        nodes.push(n);
   223→        if (stateNode) edges.push({ fn: stateNode.id, fp: 0, tn: n.id, tp: 0 });
   224→      } else if (c === 'input') {
   225→        n = NODE.input('입력하세요');
   226→        nodes.push(n);
   227→      } else if (c === 'card') {
   228→        n = NODE.card(keywords.title ?? '카드');
   229→        nodes.push(n);
   230→      }
   231→
   232→      if (container && n) {
   233→        edges.push({ fn: n.id, fp: 0, tn: container.id, tp: 0 });
   234→      }
   235→    }
   236→
   237→    return { nodes, edges, label: intent.raw };
   238→  }
   239→
   240→  _generateFallback(raw) {
   241→    const t = NODE.text(raw.slice(0, 20), 'p');
   242→    const b = NODE.button('확인');
   243→    const c = NODE.container();
   244→    return {
   245→      nodes: [c, t, b],
   246→      edges: [
   247→        { fn: t.id, fp: 0, tn: c.id, tp: 0 },
   248→        { fn: b.id, fp: 0, tn: c.id, tp: 0 },
   249→      ],
   250→      label: raw,
   251→    };
   252→  }
   253→}
