   642→  /**
   643→   * 텍스트 → 그래프 JSON
   644→   * @param {string} text - 자연어 설명
   645→   * @param {{ offsetX?, offsetY?, existingNodes? }} opts
   646→   * @returns {{ nodes: object, edges: object[], label: string, intent: string }}
   647→   */
   648→  async generate(text, opts = {}) {
   649→    // 1) 의도 파악
   650→    const intent = this.parser.parse(text);
   651→
   652→    // 2) LLM 있으면 시도
   653→    if (this.llmEndpoint) {
   654→      try {
   655→        const llmResult = await this._callLLM(text);
   656→        if (llmResult) return this._finalize(llmResult, opts, intent.type);
   657→      } catch { /* LLM 실패 시 규칙 기반으로 폴백 */ }
   658→    }
   659→
   660→    // 3) 템플릿/규칙 기반 생성
   661→    const raw = this.templates.generate(intent);
   662→
   663→    return this._finalize(raw, opts, intent.type);
   664→  }
   665→
   666→  _finalize(raw, opts, intentType) {
   667→    const { offsetX = 100, offsetY = 80 } = opts;
   668→
   669→    // 위치 계산
   670→    const positions = this.layout.layout(raw.nodes, raw.edges, offsetX, offsetY);
   671→
   672→    // 노드 객체화
   673→    const nodes = {};
   674→    for (const n of raw.nodes) {
   675→      nodes[n.id] = {
   676→        ...n,
   677→        position: positions[n.id] ?? { x: offsetX, y: offsetY },
   678→      };
   679→    }
   680→
   681→    // 엣지 ID 부여
   682→    const edges = raw.edges.map((e, i) => ({ id: e.id ?? `ae-${i}`, ...e }));
   683→
   684→    return {
   685→      nodes,
   686→      edges,
   687→      label: raw.label,
   688→      intent: intentType,
   689→      nodeCount: raw.nodes.length,
   690→      edgeCount: edges.length,
   691→    };
   692→  }
   693→
   694→  /**
   695→   * LLM API 연동 (로컬 서버 or Claude API)
   696→   */
   697→  async _callLLM(text) {
   698→    const SYSTEM = `You are a FreeWire node graph generator.
   699→Given a UI description, return a JSON graph with nodes and edges.
   700→Node types: component (button/text/input/card/container), data (state/const/array), logic (handler/setState/condition).
   701→Return only valid JSON: { "nodes": [...], "edges": [...], "label": "..." }`;
   702→
   703→    const res = await fetch(this.llmEndpoint, {
   704→      method: 'POST',
   705→      headers: { 'Content-Type': 'application/json' },
   706→      body: JSON.stringify({ system: SYSTEM, message: text }),
   707→    });
   708→
   709→    if (!res.ok) throw new Error('LLM API error');
   710→    const data = await res.json();
   711→
   712→    // 응답에서 JSON 추출 (brace 카운팅으로 완전한 객체 추출)
   713→    const raw = data.content ?? data.text ?? '';
   714→    const start = raw.indexOf('{');
   715→    if (start === -1) throw new Error('No JSON in LLM response');
   716→    let depth = 0, end = -1;
   717→    for (let i = start; i < raw.length; i++) {
   718→      if (raw[i] === '{') depth++;
   719→      else if (raw[i] === '}') { depth--; if (depth === 0) { end = i + 1; break; } }
   720→    }
   721→    if (end === -1) throw new Error('Incomplete JSON in LLM response');
   722→    return JSON.parse(raw.slice(start, end));
   723→  }
   724→
   725→  /**
   726→   * LLM 서버 설정
   727→   */
   728→  setLLMEndpoint(url) {
   729→    this.llmEndpoint = url;
   730→  }
   731→
   732→  /**
   733→   * 지원 의도 목록
   734→   */
   735→  getSupportedIntents() {
   736→    return [
   737→      { intent: 'login', example: '로그인 폼 만들어줘' },
   738→      { intent: 'register', example: '회원가입 폼' },
   739→      { intent: 'counter', example: '카운터 앱' },
   740→      { intent: 'search', example: '검색 UI' },
   741→      { intent: 'todo', example: '할 일 리스트' },
   742→      { intent: 'profile-card', example: '프로필 카드' },
   743→      { intent: 'comment-form', example: '댓글 폼' },
   744→      { intent: 'checkout', example: '결제 폼' },
   745→      { intent: 'settings', example: '설정 페이지' },
   746→      { intent: 'dashboard', example: '대시보드' },
   747→      { intent: 'modal', example: '모달 팝업' },
   748→      { intent: 'navbar', example: '네비게이션 바' },
   749→      { intent: 'single-button', example: '버튼 하나만' },
   750→      { intent: 'single-card', example: '카드 UI' },
   751→      { intent: 'input-form', example: '입력 폼' },
   752→    ];
   753→  }
   754→}
   755→
   756→module.exports = { AINodeGenerator, IntentParser, TemplateEngine, LayoutEngine };
