test('노드 ID가 순차적으로 증가', () => {
  const g = new GraphModel();
  const id1 = g.addNode({ type:'data', subtype:'const', label:'a', inputs:[], outputs:[], props:{} });
  const id2 = g.addNode({ type:'data', subtype:'const', label:'b', inputs:[], outputs:[], props:{} });
  const num1 = parseInt(id1.slice(1), 10);
  const num2 = parseInt(id2.slice(1), 10);
  assert(num2 === num1 + 1, `ID 비연속: ${id1}, ${id2}`);
});

test('존재하지 않는 노드 제거해도 오류 없음', () => {
