  eq(g.nodes.size, 0);
});

test('addWire 중복 시 null 반환', () => {
  const g = new GraphModel();
  const n1 = g.addNode({ type:'data', subtype:'const', label:'c', inputs:[], outputs:[{name:'v',portType:'data'}], props:{} });
  const n2 = g.addNode({ type:'component', subtype:'text', label:'t', inputs:[{name:'c',portType:'data'}], outputs:[], props:{} });
  const id1 = g.addWire(n1, 0, n2, 0, 'data');
  const id2 = g.addWire(n1, 0, n2, 0, 'data');
  assert(id1 !== null, '첫 번째 와이어는 id 반환 필요');
  assert(id2 === null, '중복 와이어는 null 반환 필요');
});

test('toJSON → fromJSON 와이어 필드 모두 보존', () => {
  const g = new GraphModel();
  const n1 = g.addNode({ type:'data', subtype:'const', label:'c', inputs:[], outputs:[{name:'v',portType:'data'}], props:{} });
  const n2 = g.addNode({ type:'component', subtype:'text', label:'t', inputs:[{name:'c',portType:'data'}], outputs:[], props:{} });
  g.addWire(n1, 0, n2, 0, 'data');
  const json = g.toJSON();
  const g2 = new GraphModel();
  g2.fromJSON(json);
  const wire = [...g2.wires.values()][0];
  assert(wire.fn === n1, `fn 불일치: ${wire.fn}`);
  assert(wire.tn === n2, `tn 불일치: ${wire.tn}`);
  assert(wire.pt === 'data', `pt 불일치: ${wire.pt}`);
});

test('fromJSON 빈 객체 처리 (nodes/edges 없음)', () => {
  const g = new GraphModel();
  g.fromJSON({});
  eq(g.nodes.size, 0);
  eq(g.wires.size, 0);
});

